// Shapes of the files generated by scripts/build-index.mjs (see docs/SITE-SPEC.md).

export interface MarketplaceInfo {
  name: string;
  description: string;
  owner: string;
  repository: string | null;
  githubSlug: string | null;
}

export interface Dependency {
  name: string;
  version: string | null;
}

export interface Plugin {
  id: string;
  type: 'plugin';
  name: string;
  version: string;
  description: string;
  keywords: string[];
  category: string | null;
  tags: string[];
  author: string;
  license: string;
  dependencies: Dependency[];
  dependents: string[];
  skills: string[];
  agents: string[];
  evals: string[];
  minClaudeCode: string | null;
  install: string;
  body: string;
  changelog: string | null;
  compatibility: string | null;
  sourcePath: string;
  searchText: string;
}

interface ArtifactBase {
  id: string;
  name: string;
  namespacedName: string;
  plugin: string;
  description: string;
  body: string;
  sourcePath: string;
  searchText: string;
}

export interface SkillArtifact extends ArtifactBase {
  type: 'skill';
  manualOnly: boolean;
  argumentHint: string | null;
  thirdParty: boolean;
}

export interface AgentArtifact extends ArtifactBase {
  type: 'agent';
  model: string | null;
  tools: string[];
  disallowedTools: string[];
}

export type Artifact = SkillArtifact | AgentArtifact;
export type Entry = Plugin | Artifact;
export type EntryType = Entry['type'];

export interface CatalogIndex {
  generatedAt: string;
  marketplace: MarketplaceInfo;
  plugins: Plugin[];
  artifacts: Artifact[];
}

export interface Release {
  plugin: string;
  version: string;
  tag: string;
  released: boolean;
  date: string | null;
  notes: string;
}

export interface Stats {
  plugins: number;
  skills: number;
  agents: number;
  evalCases: number;
  thirdPartySkills: number;
  releasedVersions: number;
  commit: string | null;
  generatedAt: string;
}

export interface CatalogData {
  index: CatalogIndex;
  releases: Release[];
  stats: Stats;
}
